const items = $json.items || [];
const scored = items.map(i => {
  const body = (i.body || '');
  const m = body.match(/\$([0-9]+(?:\.[0-9]+)?)/) || (i.title||'').match(/\$([0-9]+(?:\.[0-9]+)?)/);
  const reward = m ? parseFloat(m[1]) : 0;
  const ageH = (Date.now() - new Date(i.created_at).getTime()) / 36e5;
  const crowdPenalty = Math.min(i.comments || 0, 10);
  const score = reward * 2 + Math.max(0, 72 - ageH) - crowdPenalty * 5;
  return { title: i.title, url: i.html_url, repo: i.repository_url.split('/').slice(-2).join('/'), reward, comments: i.comments, score: Math.round(score) };
}).filter(i => i.reward >= 50).sort((a,b) => b.score - a.score).slice(0, 5);
return scored.map(s => ({ json: s }));

const items = $input.all();
if (!items.length) return [{ json: { text: 'No fresh bounties ≥$50 found.' } }];
const lines = items.map(i => `**$${i.json.reward}** [${i.json.title}](${i.json.url}) — ${i.json.repo} (💬${i.json.comments}, score ${i.json.score})`);
return [{ json: { text: '🎯 **Fresh GitHub Bounties**\n' + lines.join('\n') } }];
